// BeforeCreate hook for TeamMemory
func (tm *TeamMemory) BeforeCreate(tx *gorm.DB) error {
	if tm.ID == uuid.Nil {
		tm.ID = uuid.New()
	}
	if tm.CreatedAt.IsZero() {
		tm.CreatedAt = time.Now()
	}
	if tm.UpdatedAt.IsZero() {
		tm.UpdatedAt = time.Now()
	}

	if tm.TTLDays == 0 {
		switch tm.MemoryType {
		case "decision":
			tm.TTLDays = 730
		case "preference":
			tm.TTLDays = 365
		case "process":
			tm.TTLDays = 0
		case "client_context":
			tm.TTLDays = 0
		}
	}

	if tm.TTLDays > 0 && tm.ExpiresAt == nil {
		expiresAt := tm.CreatedAt.AddDate(0, 0, tm.TTLDays)
		tm.ExpiresAt = &expiresAt
	}

	return nil
}

// BeforeUpdate hook for TeamMemory
func (tm *TeamMemory) BeforeUpdate(tx *gorm.DB) error {
	tm.UpdatedAt = time.Now()

	if tm.TTLDays > 0 {
		expiresAt := tm.UpdatedAt.AddDate(0, 0, tm.TTLDays)
		tm.ExpiresAt = &expiresAt
	} else if tm.TTLDays == 0 {
		tm.ExpiresAt = nil
	}

	return nil
}

// Value implements driver.Valuer for JSONRawMessage
func (j JSONRawMessage) Value() (driver.Value, error) {
	if j == nil {
		return nil, nil
	}
	return json.Marshal(j)
}

// Scan implements sql.Scanner for JSONRawMessage - handles pgx JSONB mode
// pgx driver sends JSONB as map[string]interface{} for objects
func (j *JSONRawMessage) Scan(value interface{}) error {
	if value == nil {
		*j = nil
		return nil
	}
	switch v := value.(type) {
	case []byte:
		*j = v
		return nil
	case string:
		*j = []byte(v)
		return nil
	case map[string]interface{}:

		b, err := json.Marshal(v)
		if err != nil {
			return fmt.Errorf("cannot marshal map to JSONRawMessage: %w", err)
		}
		*j = b
		return nil
	case []interface{}:

		b, err := json.Marshal(v)
		if err != nil {
			return fmt.Errorf("cannot marshal array to JSONRawMessage: %w", err)
		}
		*j = b
		return nil
	default:
		return fmt.Errorf("cannot scan %T into JSONRawMessage", value)
	}
}

